import { Group, PlaneGeometry, Mesh, BoxGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, AmbientLight, DirectionalLight, Color } from 'three/webgpu';
import { uniform, mix, uv, vec3, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'filmstrip-carousel';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#12121a' }]
  };

  // ---- Backdrop gradient plane ----
  const gradStops = colors.gradientStops ?? [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#12121a' }];
  const c0 = new THREE.Color(gradStops[0].hex);
  const c1 = new THREE.Color(gradStops[gradStops.length - 1].hex);
  const bgGeo = new THREE.PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide
  });
  bgMat.colorNode = mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), uv().y);
  const bgPlane = new THREE.Mesh(bgGeo, bgMat);
  bgPlane.position.set(0, 0, -2.5);
  group.add(bgPlane);

  // ---- Lights ----
  const ambient = new AmbientLight(0xffffff, 0.6);
  group.add(ambient);
  const key = new DirectionalLight(0xe8ecf2, 1.2);
  key.position.set(2.5, 2.5, 3.5);
  group.add(key);
  const rim = new DirectionalLight(new THREE.Color(colors.accent), 0.8);
  rim.position.set(-3, -1.5, -2);
  group.add(rim);

  // ---- Strip group rotated -18deg on Y ----
  const stripGroup = new THREE.Group();
  stripGroup.rotation.y = THREE.MathUtils.degToRad(-18);
  group.add(stripGroup);

  // ---- Text content items ----
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find(t => t.role === 'headline') || { text: 'The collection' };
  const bodyItem = textItems.find(t => t.role === 'body') || { text: 'Five calibres. One discipline.' };
  const captionItems = textItems.filter(t => t.role === 'caption');

  const captions = captionItems.length >= 5
    ? captionItems.slice(0, 5)
    : [
      { text: 'NA-01 MERIDIAN' },
      { text: 'NA-02 NOCTURNE' },
      { text: 'NA-03 SIGNAL' },
      { text: 'NA-04 VANTAGE' },
      { text: 'NA-05 ARCHIVE' }
    ];

  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const pitch = 1.85;
  const focusIndex = 2;

  const cards = [];
  const bevels = [];
  const captionsObjs = [];
  const cardCleanups = [];

  // Load the image texture — slice into 5 distinct UV regions
  let sharedTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    sharedTexture = tex;
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.minFilter = THREE.LinearMipmapLinearFilter;
    tex.magFilter = THREE.LinearFilter;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    cards.forEach((entry, i) => {
      const mat = entry.mesh.material;
      mat.map = sharedTexture;
      // slice into 5 vertical regions
      const sliceW = 1 / 5;
      const tx = i * sliceW;
      // assign a sub-region via repeat/offset
      mat.map = sharedTexture;
      // We'll set per-card by cloning texture so each card has distinct offset
      const cardTex = sharedTexture.clone();
      cardTex.needsUpdate = true;
      cardTex.wrapS = THREE.ClampToEdgeWrapping;
      cardTex.wrapT = THREE.ClampToEdgeWrapping;
      cardTex.repeat.set(sliceW, 1);
      cardTex.offset.set(tx, 0);
      mat.map = cardTex;
      mat.needsUpdate = true;
    });
  });

  // ---- Build 5 cards ----
  for (let i = 0; i < 5; i++) {
    const x = (i - focusIndex) * pitch;
    const isFocus = i === focusIndex;
    const dist = Math.abs(i - focusIndex);

    // Bevel frame: slightly larger box behind card
    const bevelGeo = new THREE.BoxGeometry(cardWidth + 0.05, cardHeight + 0.05, 0.025);
    const bevelMat = new MeshStandardNodeMaterial({
      color: new THREE.Color(colors.ink),
      roughness: 0.5,
      metalness: 0.55,
      clearcoat: 0.25
    });
    const bevelMesh = new THREE.Mesh(bevelGeo, bevelMat);
    bevelMesh.position.set(x, 0, -0.013);
    stripGroup.add(bevelMesh);
    bevels.push(bevelMesh);

    // Card plane
    const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);
    const opacity = isFocus ? 1.0 : THREE.MathUtils.lerp(1.0, 0.55, dist / 2);
    const scale = isFocus ? 1.0 : 0.92;
    const cardMat = new MeshStandardNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      opacity: opacity,
      color: new THREE.Color(colors.surface)
    });
    const cardMesh = new THREE.Mesh(cardGeo, cardMat);
    cardMesh.position.set(x, 0, 0);
    cardMesh.scale.setScalar(scale);
    if (isFocus) {
      // counter-rotate to face camera dead-on
      cardMesh.rotation.y = THREE.MathUtils.degToRad(18);
      bevelMesh.rotation.y = THREE.MathUtils.degToRad(18);
    } else {
      cardMesh.rotation.y = 0;
      bevelMesh.rotation.y = 0;
    }
    stripGroup.add(cardMesh);
    cards.push({ mesh: cardMesh, bevel: bevelMesh, index: i, baseX: x });

    // Caption below card
    const capText = captions[i] ? captions[i].text : `NA-0${i + 1}`;
    const capObj = ctx.fontAtlas.createText(capText, {
      fontSize: 18,
      color: isFocus ? colors.accent : colors.paper,
      align: 'center',
      letterSpacingPx: 1.4
    });
    capObj.position.set(x, -0.82, 0);
    capObj.rotation.y = isFocus ? THREE.MathUtils.degToRad(18) : 0;
    // dim non-focused captions
    if (!isFocus) {
      capObj.traverse(c => {
        if (c.material) {
          c.material.transparent = true;
          c.material.opacity = opacity;
        }
      });
    }
    stripGroup.add(capObj);
    captionsObjs.push(capObj);
  }

  // ---- Focus underline bar ----
  const underlineGeo = new THREE.PlaneGeometry(1.6, 0.035);
  const underlineMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.3,
    roughness: 0.4,
    metalness: 0.3
  });
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(0, -0.55, 0.001);
  underline.rotation.y = THREE.MathUtils.degToRad(18);
  stripGroup.add(underline);

  // ---- Headline (pinned in scene, not rotated) ----
  const headlineObj = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: -0.34
  });
  headlineObj.position.set(-2.6, 1.5, 0);
  group.add(headlineObj);

  // ---- Body line ----
  const bodyObj = ctx.fontAtlas.createText(bodyItem.text, {
    fontSize: 26,
    color: colors.paper,
    align: 'left'
  });
  bodyObj.position.set(-2.6, -1.5, 0);
  group.add(bodyObj);

  // ---- Contact shadow plane under strip ----
  const shadowGeo = new THREE.PlaneGeometry(6, 1.4);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.5,
    color: new THREE.Color(0x000000),
    depthWrite: false
  });
  // radial fade via uv
  shadowMat.colorNode = mix(
    vec3(0, 0, 0),
    vec3(0.043, 0.043, 0.063),
    smoothstep(0, 0.7, uv().x.clone().mul(uv().x.clone()).add(uv().y.clone().mul(uv().y.clone())).sqrt())
  );
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -1.1, -0.1);
  shadowPlane.rotation.x = THREE.MathUtils.degToRad(-90);
  group.add(shadowPlane);

  // ---- Parallax-scroll primitive ----
  const primCleanups = [];
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    if (p.name === 'parallax-scroll' && ctx.primitives && ctx.primitives['parallax-scroll']) {
      const params = { ...p.params };
      try {
        const r = ctx.primitives['parallax-scroll'](stripGroup, params);
        if (r && r.cleanup) primCleanups.push(r.cleanup);
      } catch (e) { /* primitive may not be available */ }
    }
  }

  // ---- GSAP entrance ----
  const tl = gsap.timeline();
  group.userData._tl = tl;
  group.scale.set(1, 1, 1);
  group.position.y = 0.4;
  group.opacity = 0;
  tl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  // animate headline / body fade-up
  headlineObj.position.y += 0.2;
  bodyObj.position.y += 0.2;
  tl.to(headlineObj.position, { y: 1.5, duration: 0.6, ease: 'power2.out' }, 0.1);
  tl.to(bodyObj.position, { y: -1.5, duration: 0.6, ease: 'power2.out' }, 0.25);

  // ---- Interaction handlers ----
  group.userData.handlers = {
    click: (e) => {
      // emit navigate on click of a card? spec says no interactions, but keep safe
    },
    hover: (e) => {}
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    primCleanups.forEach(fn => { try { fn(); } catch (e) {} });
    cards.forEach(c => {
      c.mesh.geometry.dispose();
      if (c.mesh.material.map && c.mesh.material.map !== sharedTexture) c.mesh.material.map.dispose();
      c.mesh.material.dispose();
    });
    bevels.forEach(b => { b.geometry.dispose(); b.material.dispose(); });
    captionsObjs.forEach(c => {
      c.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
    });
    underlineGeo.dispose(); underlineMat.dispose();
    bgGeo.dispose(); bgMat.dispose();
    shadowGeo.dispose(); shadowMat.dispose();
    headlineObj.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
    bodyObj.traverse(o => { if (o.geometry) o.geometry.dispose(); if (o.material) o.material.dispose(); });
  };

  return group;
}
